		var best *cand
		var pathmatch []string
		for _, r := range routes {
			caps, ok := match(r.segs, segs)
			if !ok {
				continue
			}
			pathmatch = append(pathmatch, r.method)
			if r.method == "*" || r.method == method || (method == "HEAD" && r.method == "GET") {
				spec := make([]int, len(r.segs))
				for i, s := range r.segs {
