				}
				exact := 0
				if r.method == method {
					exact = 2
				} else if r.method == "*" {
					exact = 1
				}
				c := &cand{spec, exact, r.handler, caps}
				if best == nil {
					best = c
					continue
				}
				n := len(c.spec)
				if len(best.spec) > n {
					n = len(best.spec)
				}
				cmp := 0
				for k := 0; k < n && cmp == 0; k++ {
					a, b := -1, -1
					if k < len(c.spec) {
						a = c.spec[k]
					}
					if k < len(best.spec) {
						b = best.spec[k]
					}
					cmp = a - b
				}
				if cmp == 0 {
					cmp = c.exact - best.exact
				}
				if cmp > 0 {
					best = c
				}
			}
		}
		switch {
		case best != nil:
			parts := []string{"200", best.handler}
			for _, c := range best.caps {
				parts = append(parts, c.k+"="+c.v)
			}
			out = append(out, strings.Join(parts, " "))
		case len(pathmatch) > 0:
			allowed := map[string]bool{}
			for _, m := range pathmatch {
				switch m {
				case "*":
					for _, x := range methods {
						allowed[x] = true
					}
				case "GET":
					allowed["GET"] = true
					allowed["HEAD"] = true
				default:
					allowed[m] = true
				}
			}
			var l []string
			for _, x := range methods {
				if allowed[x] {
					l = append(l, x)
				}
			}
			out = append(out, "405 allow="+strings.Join(l, ","))
		default:
			out = append(out, "404")
		}
	}
	return strings.Join(out, "\n")
}

