const (
	hasMethods = true
	hasWild    = true
	lenient    = true
	caseI      = true
	hasPct     = true
	low        = "abcdefghijklmnopqrstuvwxyz"
	up         = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
	dg         = "0123456789"
	hexc       = "0123456789abcdefABCDEF"
)

var types = []string{"hex", "alpha"}
var methods = []string{"GET", "HEAD", "POST", "PUT", "PATCH", "DELETE"}

type seg struct{ kind, name, typ string }

type rt struct {
	method  string
	segs    []seg
	handler string
}

func allIn(s, set string) bool {
	for i := 0; i < len(s); i++ {
		if !strings.ContainsRune(set, rune(s[i])) {
			return false
		}
	}
	return true
}

func ident(s string, max int) bool {
	return len(s) >= 1 && len(s) <= max && strings.ContainsRune(low, rune(s[0])) && allIn(s, low+dg+"_")
}

func inList(l []string, s string) bool {
	for _, x := range l {
		if x == s {
			return true
		}
	}
	return false
}

func parsePattern(p string) ([]seg, bool) {
	if p == "/" {
		return []seg{}, true
	}
	if !strings.HasPrefix(p, "/") || strings.HasSuffix(p, "/") {
		return nil, false
	}
	var segs []seg
	names := map[string]bool{}
	parts := strings.Split(p[1:], "/")
	for i, s := range parts {
		if s == "" {
			return nil, false
		}
		switch s[0] {
		case ':':
			body := s[1:]
			typ := ""
			if strings.Contains(body, "<") {
				if !strings.HasSuffix(body, ">") || strings.Count(body, "<") != 1 {
					return nil, false
				}
				sp := strings.Split(body[:len(body)-1], "<")
				body, typ = sp[0], sp[1]
				if !inList(types, typ) {
					return nil, false
				}
			}
			if !ident(body, 16) || names[body] {
				return nil, false
			}
			names[body] = true
			kind := "param"
			if typ != "" {
				kind = "typed"
			}
			segs = append(segs, seg{kind, body, typ})
		case '*':
			if !hasWild || i != len(parts)-1 || !ident(s[1:], 16) || names[s[1:]] {
				return nil, false
			}
			segs = append(segs, seg{"wild", s[1:], ""})
		default:
			if !allIn(s, low+up+dg+"._~-") {
				return nil, false
			}
			segs = append(segs, seg{"lit", s, ""})
		}
	}
	return segs, true
}

func typeOk(typ, s string) bool {
	switch typ {
	case "int":
		return len(s) >= 1 && len(s) <= 9 && allIn(s, dg)
	case "slug":
		return s != "" && allIn(s, low+dg+"-") && !strings.HasPrefix(s, "-") && !strings.HasSuffix(s, "-") && !strings.Contains(s, "--")
	case "alpha":
		return s != "" && allIn(s, low+up)
	}
	return s != "" && allIn(s, hexc)
}

type cap2 struct{ k, v string }

func match(segs []seg, path []string) ([]cap2, bool) {
	var caps []cap2
	i := 0
	for _, sg := range segs {
		if sg.kind == "wild" {
			if i >= len(path) {
				return nil, false
			}
			caps = append(caps, cap2{sg.name, strings.Join(path[i:], "/")})
			return caps, true
		}
		if i >= len(path) {
			return nil, false
		}
		s := path[i]
		if sg.kind == "lit" {
			if caseI {
				if strings.ToLower(s) != strings.ToLower(sg.name) {
					return nil, false
				}
			} else if s != sg.name {
				return nil, false
			}
		} else {
			if s == "" {
				return nil, false
			}
			if sg.kind == "typed" && !typeOk(sg.typ, s) {
				return nil, false
			}
			caps = append(caps, cap2{sg.name, s})
		}
		i++
	}
	return caps, i == len(path)
}

func decode(s string) (string, bool) {
	var out []byte
	for i := 0; i < len(s); {
		c := s[i]
		if c == '%' {
			if i+3 > len(s) {
				return "", false
			}
			h := s[i+1 : i+3]
			if !allIn(h, hexc) {
				return "", false
			}
			v, _ := strconv.ParseUint(h, 16, 8)
			c = byte(v)
			i += 3
		} else {
			i++
		}
		if c < ' ' || c > '~' {
			return "", false
		}
		out = append(out, c)
	}
	return string(out), true
}

func rank(k string) int {
	switch k {
	case "lit":
		return 3
	case "typed":
		return 2
	case "param":
		return 1
	}
	return 0
}

func parseTable(text string) ([]rt, string) {
	var routes []rt
	for i, raw := range strings.Split(text, "\n") {
		if h := strings.IndexByte(raw, '#'); h >= 0 {
			raw = raw[:h]
		}
		w := strings.Fields(raw)
		if len(w) == 0 {
			continue
		}
		err := func(m string) string { return fmt.Sprintf("error: table line %d: %s", i+1, m) }
		want := 2
		if hasMethods {
			want = 3
		}
		if len(w) != want {
			return nil, err("bad directive")
		}
		method := "*"
		if hasMethods {
			method = w[0]
			if method != "*" && !inList(methods, method) {
				return nil, err("bad method")
			}
		}
		segs, ok := parsePattern(w[len(w)-2])
		if !ok {
			return nil, err("bad pattern")
		}
		if !ident(w[len(w)-1], 24) {
			return nil, err("bad handler")
		}
		routes = append(routes, rt{method, segs, w[len(w)-1]})
	}
	return routes, ""
}

type cand struct {
	spec    []int
	exact   int
	handler string
	caps    []cap2
}

// Route answers one line per request.
func Route(table, requests string) string {
	routes, errText := parseTable(table)
	if errText != "" {
		return errText
	}
	var out []string
	for _, raw := range strings.Split(requests, "\n") {
		if strings.HasPrefix(strings.TrimLeft(raw, " \t"), "#") {
			continue
		}
		w := strings.Fields(raw)
		if len(w) == 0 {
			continue
		}
		want := 1
		if hasMethods {
			want = 2
		}
		if len(w) != want {
			out = append(out, "400")
			continue
		}
		method := "GET"
		if hasMethods {
			method = w[0]
			ok := len(method) > 0
			for i := 0; i < len(method); i++ {
				if method[i] < 'A' || method[i] > 'Z' {
					ok = false
				}
			}
			if !ok {
				out = append(out, "400")
				continue
			}
		}
		path := w[len(w)-1]
		if q := strings.IndexByte(path, '?'); q >= 0 {
			path = path[:q]
		}
		if !strings.HasPrefix(path, "/") {
			out = append(out, "400")
			continue
		}
		body := path[1:]
		var segs []string
		if path == "/" {
			segs = []string{}
		} else {
			if lenient && strings.HasSuffix(body, "/") {
				body = body[:len(body)-1]
			}
			segs = strings.Split(body, "/")
			bad := len(segs) == 1 && segs[0] == "" && body == ""
			for _, s := range segs[:len(segs)-1] {
				if s == "" {
					bad = true
				}
			}
			if bad {
				out = append(out, "400")
				continue
			}
		}
		if hasPct {
			dec := make([]string, 0, len(segs))
			bad := false
			for _, s := range segs {
				d, ok := decode(s)
				if !ok {
					bad = true
					break
				}
				dec = append(dec, d)
			}
			if bad {
				out = append(out, "400")
				continue
			}
			segs = dec
		}
		var best *cand
		var pathmatch []string
		for _, r := range routes {
			caps, ok := match(r.segs, segs)
			if !ok {
				continue
			}
			pathmatch = append(pathmatch, r.method)
			if r.method == "*" || r.method == method || (method == "HEAD" && r.method == "GET") {
				spec := make([]int, len(r.segs))
				for i, s := range r.segs {
					spec[i] = rank(s.kind)
				}
				exact := 0
				if r.method == method {
					exact = 2
				} else if r.method == "*" {
					exact = 1
				}
				c := &cand{spec, exact, r.handler, caps}
				if best == nil {
					best = c
					continue
				}
				n := len(c.spec)
				if len(best.spec) > n {
					n = len(best.spec)
				}
				cmp := 0
				for k := 0; k < n && cmp == 0; k++ {
					a, b := -1, -1
					if k < len(c.spec) {
						a = c.spec[k]
					}
					if k < len(best.spec) {
						b = best.spec[k]
					}
					cmp = a - b
				}
				if cmp == 0 {
					cmp = c.exact - best.exact
				}
				if cmp > 0 {
					best = c
				}
			}
		}
		switch {
		case best != nil:
			parts := []string{"200", best.handler}
			for _, c := range best.caps {
				parts = append(parts, c.k+"="+c.v)
			}
			out = append(out, strings.Join(parts, " "))
		case len(pathmatch) > 0:
			allowed := map[string]bool{}
			for _, m := range pathmatch {
				switch m {
				case "*":
					for _, x := range methods {
						allowed[x] = true
					}
				case "GET":
					allowed["GET"] = true
					allowed["HEAD"] = true
				default:
					allowed[m] = true
				}
			}
			var l []string
			for _, x := range methods {
				if allowed[x] {
					l = append(l, x)
				}
			}
			out = append(out, "405 allow="+strings.Join(l, ","))
		default:
			out = append(out, "404")
		}
	}
	return strings.Join(out, "\n")
}

